// Normaliza payload da Meta Cloud API
// Extrai mensagens de texto, ignora status/eventos
const entries = $input.first().json.body?.entry || [];
const messages = [];
for (const entry of entries) {
  for (const change of entry.changes || []) {
    const value = change.value || {};
    const contacts = value.contacts || [];
    for (const msg of value.messages || []) {
      if (msg.type !== 'text') continue;
      const contact = contacts.find(c => c.wa_id === msg.from) || contacts[0];
      messages.push({
        messageId: msg.id,
        phone: msg.from,
        name: contact?.profile?.name || 'Cliente',
        text: msg.text?.body || '',
        phoneNumberId: value.metadata?.phone_number_id || '',
        timestamp: msg.timestamp
      });
    }
  }
}
return messages.map(m => ({ json: m }));

// Idempotência: dedupe por messageId (cache em memória do n8n)
// O backend também deduplica via unique messageId no banco.
const seen = new Set();
return $input.all().filter(item => {
  const id = item.json.messageId;
  if (seen.has(id)) return false;
  seen.add(id);
  return true;
});

// Resposta do backend já inclui a resposta pronta para o cliente.
// Nenhuma regra de negócio aqui — o backend é a fonte da verdade.
return $input.all();
